import{_ as t,o as a,c as r,a6 as o}from"./chunks/framework.DIp0zHSV.js";const p=JSON.parse('{"title":"Alert Mode Lab","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/alert-mode-lab.md","filePath":"configuration/alert-mode-lab.md","lastUpdated":1791851330000}'),l={name:"configuration/alert-mode-lab.md"};function s(n,e,d,i,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="alert-mode-lab" tabindex="-1">Alert Mode Lab <a class="header-anchor" href="#alert-mode-lab" aria-label="Permalink to &quot;Alert Mode Lab&quot;">​</a></h1><p>The <strong>Alert Mode Lab</strong> is a tab in the <a href="./">LCARdS Config Panel</a> for customising the colour palette applied to each alert level. Changes can be previewed live before saving.</p><hr><h2 id="what-it-does" tabindex="-1">What It Does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What It Does&quot;">​</a></h2><p>LCARdS Alert Mode shifts card colours across your entire dashboard when an alert is active. The Lab lets you tune how each alert level looks by adjusting per-mode colour parameters, then saves those values as HA input helpers so they persist across restarts.</p><hr><h2 id="accessing-the-lab" tabindex="-1">Accessing the Lab <a class="header-anchor" href="#accessing-the-lab" aria-label="Permalink to &quot;Accessing the Lab&quot;">​</a></h2><ol><li>Open the <strong>LCARdS Config Panel</strong> (sidebar entry in Home Assistant)</li><li>Open the <strong>Theme Studio</strong> tab; the <strong>LCARdS Alert Mode Lab</strong> is its first tab</li></ol><div class="tip custom-block"><p class="custom-block-title">Prerequisites</p><p><a href="./persistent-helpers.html">Persistent helpers</a> must exist before saving Lab settings. Run <strong>Create All Helpers</strong> from the Helpers tab first.</p></div><hr><h2 id="per-mode-parameters" tabindex="-1">Per-Mode Parameters <a class="header-anchor" href="#per-mode-parameters" aria-label="Permalink to &quot;Per-Mode Parameters&quot;">​</a></h2><p>Each alert level (<code>red_alert</code>, <code>yellow_alert</code>, <code>blue_alert</code>, <code>gray_alert</code>, <code>black_alert</code>) has its own set of colour parameters.</p><h3 id="hsl-parameters" tabindex="-1">HSL Parameters <a class="header-anchor" href="#hsl-parameters" aria-label="Permalink to &quot;HSL Parameters&quot;">​</a></h3><p>These shift the overall colour of cards while that mode is active.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><strong>Hue</strong></td><td>Base hue shift (0–360°) applied to all colours</td></tr><tr><td><strong>Hue Strength</strong></td><td>How strongly the hue shift is applied (0–1)</td></tr><tr><td><strong>Saturation</strong></td><td>Overall saturation adjustment</td></tr><tr><td><strong>Lightness</strong></td><td>Overall lightness adjustment</td></tr></tbody></table><h3 id="anchor-parameters-red-yellow-blue" tabindex="-1">Anchor Parameters <em>(Red, Yellow, Blue)</em> <a class="header-anchor" href="#anchor-parameters-red-yellow-blue" aria-label="Permalink to &quot;Anchor Parameters *(Red, Yellow, Blue)*&quot;">​</a></h3><p>Anchor parameters lock specific colours to a target hue, useful for keeping key UI elements (like accent colours) visually correct even under a hue shift.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><strong>Anchor Center Hue</strong></td><td>The hue value to anchor (the colour you want to protect)</td></tr><tr><td><strong>Anchor Range</strong></td><td>How wide a hue band around the center is affected</td></tr><tr><td><strong>Anchor Strength</strong></td><td>How strongly the anchor effect is applied (0–1)</td></tr></tbody></table><h3 id="contrast-parameters-black" tabindex="-1">Contrast Parameters <em>(Black)</em> <a class="header-anchor" href="#contrast-parameters-black" aria-label="Permalink to &quot;Contrast Parameters *(Black)*&quot;">​</a></h3><p>The <code>black_alert</code> mode uses contrast parameters instead of hue anchors to create the near-monochrome blackout effect.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><strong>Contrast Threshold</strong></td><td>Lightness threshold below which colours are pushed dark</td></tr><tr><td><strong>Dark Multiplier</strong></td><td>Multiplier applied to dark colours (&lt; threshold)</td></tr><tr><td><strong>Light Multiplier</strong></td><td>Multiplier applied to light colours (&gt; threshold)</td></tr></tbody></table><hr><h2 id="live-preview" tabindex="-1">Live Preview <a class="header-anchor" href="#live-preview" aria-label="Permalink to &quot;Live Preview&quot;">​</a></h2><p>Changes in the Lab are reflected in real time on any open Lovelace dashboard. You can switch between alert levels and adjust parameters while watching the effect on your actual cards before committing.</p><hr><h2 id="saving-settings" tabindex="-1">Saving Settings <a class="header-anchor" href="#saving-settings" aria-label="Permalink to &quot;Saving Settings&quot;">​</a></h2><p>Click <strong>Save</strong> in the Lab to write all current parameter values to their corresponding <code>input_number</code> helpers. These helpers are created and managed automatically; you don&#39;t need to set them up manually.</p><p>Helper naming convention: <code>input_number.lcards_alert_lab_&lt;mode&gt;_&lt;parameter&gt;</code>, for example:</p><ul><li><code>input_number.lcards_alert_lab_red_hue</code></li><li><code>input_number.lcards_alert_lab_yellow_saturation</code></li><li><code>input_number.lcards_alert_lab_black_threshold</code></li></ul><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../core/alert-mode.html">Alert Mode</a>: how alert mode works, how to trigger it, and how cards respond</li><li><a href="./persistent-helpers.html">Persistent Helpers</a>: full helper reference including alert Lab parameters</li><li><a href="./../core/sounds.html">Sounds</a>: per-mode sound events fired when alert mode changes</li></ul>',32)])])}const m=t(l,[["render",s]]);export{p as __pageData,m as default};
